papers.theorem_field:
Let $R$ be a non-discrete irreducible, continuous ring. \begin{enumerate}
	\item\label{theorem:width.involutions} Every element of $\GL(R)$ is a product of $16$ involutions.
	\item\label{theorem:width.commutators} Every element of $\GL(R)$ is a product of $7$ commutators. In particular, $\GL(R)$ is perfect.
	\item\label{theorem:width.word} Suppose that $\ZZ(R)$ is algebraically closed. For all $m \in \N$ and $w \in \free (m)\setminus \{ \epsilon \}$,
				\begin{displaymath}
					\qquad \GL(R) \, = \, w(\GL(R))^{14} .
				\end{displaymath} In particular, $\GL(R)$ is verbally simple.
\end{enumerate}

papers.theorem_statement:
Let $R$ be a non-discrete irreducible, continuous ring. \begin{enumerate}
 \item Every simply special element of $R$ is a commutator in $\GL(R)$.
 \item Suppose that $\ZZ(R)$ is algebraically closed. If $m \in \N$ and $w \in \free (m)\setminus \{ \epsilon \}$, then every simply special element of $R$ belongs to $w(\GL(R))^{2}$.
\end{enumerate}

