Let $\omep$ be defined by (\ref{defn:omep}), and let $\PMF_{\ep}(\beta,f,(0,1),u)$ be defined by (\ref{defn:SPM}), where $\ep\in(0,1)$ and $\beta>0$ are two real numbers, and $f\in L^{2}((0,1))$ is a given function. 

Then the following facts hold true.

\begin{enumerate}
\renewcommand{\labelenumi}{(\arabic{enumi})}

\item \emph{(Existence)} There exists
\begin{equation}
m(\ep,\beta,f):=\min\left\{\PMF_{\ep}(\beta,f,(0,1),u):u\in H^{2}((0,1))\strut\right\}.

\end{equation} 

\item \emph{(Regularity)} Every minimizer belongs to $H^{4}((0,1))$, and in particular to $C^{2}([0,1])$.

\item \emph{(Minimum values vanish in the limit)} It turns out that $m(\ep,\beta,f)\to 0$ as $\ep\to 0^{+}$.

\item \emph{(Convergence of minimizers to the fidelity term)} If $\{u_{\ep}\}$ is any family of minimizers for (\ref{defn:DMnf}), then $u_{\ep}(x)\to f(x)$ in $L^{2}((0,1))$ as $\ep\to 0^{+}$.

\end{enumerate}

