\item[ $(ii)$] (Pointwise invariance property) For each $\bar u \in K$ there exists $\bar{v}\in K$ such that 

\[-\Delta \bar{v}+\lambda \bar v= a(x)|\bar{u}|^{p-2}\bar{u},\] 

in the weak sense, i.e.,
\[\int_\Omega \nabla \bar v \cdot \nabla\eta \, dx +\lambda \int_\Omega\bar v\eta \, dx =\int_\Omega a(x)|\bar{u}|^{p-2}\bar{u}\eta\, dx, \qquad \forall \eta \in H_0^1(\Omega)\cap L_a^p(\Omega).\]
\end{enumerate} 
